head.b:skin:
:root {
  --yellow: #FFD21F;
  --yellow-soft: #FFF4C2;
  --black: #111111;
  --ink: #1d1d1d;
  --muted: #4d4d4d;
  --white: #ffffff;
  --radius: 22px;
  --shadow: 6px 6px 0 var(--black);
  --font-display: 'Fredoka', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-body: 'Nunito', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--white); color: var(--ink); font-family: var(--font-body); font-size: 17px; line-height: 1.6; overflow-x: hidden; }
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; }
h1, h2, h3 { font-family: var(--font-display); font-weight: 700; line-height: 1.1; }
.wrap { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.skip-link { position: absolute; left: -999px; top: 8px; z-index: 100; background: var(--black); color: var(--yellow); padding: 10px 16px; border-radius: 10px; font-weight: 800; }
.skip-link:focus { left: 8px; }
:focus-visible { outline: 3px solid var(--black); outline-offset: 3px; }
.story :focus-visible, .site-footer :focus-visible { outline-color: var(--yellow); }
.hl { background: linear-gradient(transparent 58%, var(--yellow) 58%); padding: 0 .1em; }

/* ---------- Header ---------- */
.site-header { position: sticky; top: 0; z-index: 50; background: var(--white); border-bottom: 3px solid var(--black); }
.site-header .wrap { display: flex; align-items: center; justify-content: space-between; gap: 16px; height: 72px; }
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; font-family: var(--font-display); font-weight: 700; font-size: 26px; letter-spacing: .3px; }
.brand img { height: 46px; width: auto; }
.brand .tere { background: var(--yellow); border: 2px solid var(--black); border-radius: 8px; padding: 0 6px; margin-left: 1px; }
.main-nav { display: flex; align-items: center; gap: 4px; }
.main-nav a { text-decoration: none; font-weight: 800; padding: 8px 14px; border-radius: 999px; }
.main-nav a:hover { background: var(--yellow-soft); }
.main-nav .nav-cta { background: var(--black); color: var(--yellow); margin-left: 6px; white-space: nowrap; }
.main-nav .nav-cta:hover { background: var(--black); transform: translateY(-1px); }

/* ---------- Buttons ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 52px; padding: 12px 22px; border: 3px solid var(--black); border-radius: 14px; font: 800 16px/1.2 var(--font-body); text-decoration: none; cursor: pointer; box-shadow: 4px 4px 0 var(--black); transition: transform .15s ease, box-shadow .15s ease, background .15s ease; }
.btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--black); }
.btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 var(--black); }
.btn svg { width: 24px; height: 24px; flex: none; fill: currentColor; }
.btn .ico-stroke { fill: none; stroke: currentColor; }
.btn-black { background: var(--black); color: var(--yellow); }
.btn-white { background: var(--white); color: var(--black); }
.btn-yellow { background: var(--yellow); color: var(--black); }

/* ---------- Hero ---------- */
.hero { position: relative; overflow: hidden; background: var(--yellow); border-bottom: 3px solid var(--black); }
.hero::before { content: ''; position: absolute; inset: 0; background-image: radial-gradient(rgba(0,0,0,.13) 2px, transparent 2.6px); background-size: 28px 28px; pointer-events: none; }
.hero .wrap { position: relative; display: grid; grid-template-columns: 1.25fr .75fr; gap: 40px; align-items: center; padding-top: 64px; padding-bottom: 76px; }
.eyebrow { display: inline-block; background: var(--black); color: var(--yellow); font-weight: 800; font-size: 14px; letter-spacing: .6px; text-transform: uppercase; padding: 6px 14px; border-radius: 999px; }
.hero h1 { font-size: clamp(36px, 5.6vw, 64px); margin: 18px 0 16px; }
.hero h1 .white { background: var(--white); border: 3px solid var(--black); border-radius: 14px; padding: 0 .18em; display: inline-block; transform: rotate(-1.5deg); }
.hero .lead { font-size: clamp(17px, 2vw, 20px); max-width: 620px; margin: 0; }
.trust { list-style: none; margin: 24px 0 30px; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
.trust li { background: var(--white); border: 2px solid var(--black); border-radius: 999px; padding: 6px 14px; font-weight: 800; font-size: 15px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 14px; }

.dice-stage { position: relative; height: 340px; }
.die { position: absolute; width: 150px; height: 150px; padding: 18px; display: grid; grid-template: repeat(3, 1fr) / repeat(3, 1fr); background: var(--white); border: 4px solid var(--black); border-radius: 30px; box-shadow: 8px 8px 0 var(--black); }
.die i { width: 26px; height: 26px; border-radius: 50%; background: var(--black); place-self: center; }
.die .p1 { grid-area: 1 / 1; } .die .p3 { grid-area: 1 / 3; } .die .p4 { grid-area: 2 / 1; } .die .p5 { grid-area: 2 / 2; }
.die .p6 { grid-area: 2 / 3; } .die .p7 { grid-area: 3 / 1; } .die .p9 { grid-area: 3 / 3; }
.die-a { top: 10px; left: 6%; transform: rotate(-12deg); animation: bob 4.5s ease-in-out infinite; }
.die-b { bottom: 14px; right: 6%; transform: rotate(9deg); background: var(--black); animation: bob 4.5s ease-in-out -2.2s infinite; }
.die-b i { background: var(--yellow); }
.pawn { position: absolute; left: 44%; top: 45%; width: 54px; height: 80px; animation: bob 3.6s ease-in-out -1s infinite; }
.pawn::before { content: ''; position: absolute; left: 12px; top: 0; width: 30px; height: 30px; border-radius: 50%; background: var(--white); border: 4px solid var(--black); }
.pawn::after { content: ''; position: absolute; left: 0; bottom: 0; width: 54px; height: 52px; background: var(--white); border: 4px solid var(--black); border-radius: 50% 50% 12px 12px / 70% 70% 12px 12px; }
@keyframes bob { 0%, 100% { translate: 0 0; } 50% { translate: 0 -12px; } }

/* ---------- Sections ---------- */
.section { padding: 80px 0; }
.section-alt { background: var(--yellow-soft); border-top: 3px solid var(--black); border-bottom: 3px solid var(--black); }
.section-head { text-align: center; max-width: 740px; margin: 0 auto 44px; }
.section-head h2 { font-size: clamp(32px, 4.2vw, 48px); margin: 12px 0 12px; }
.section-head p { margin: 0; color: var(--muted); font-size: 18px; }

/* ---------- Games ---------- */
.games-grid { display: grid; grid-template-columns: 1fr; gap: 40px; }
.game-card { display: flex; flex-direction: column; background: var(--white); border: 3px solid var(--black); border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden; scroll-margin-top: 90px; }
.video { position: relative; aspect-ratio: 16 / 9; background: #000; border-bottom: 3px solid var(--black); }
.video iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.yt-lite { position: absolute; inset: 0; width: 100%; height: 100%; padding: 0; border: 0; background: #000; cursor: pointer; }
.yt-lite img { width: 100%; height: 100%; object-fit: cover; opacity: .9; }
.yt-play { position: absolute; inset: 0; margin: auto; width: 86px; height: 86px; display: grid; place-items: center; border-radius: 50%; background: var(--yellow); border: 3px solid var(--black); box-shadow: 4px 4px 0 var(--black); transition: transform .2s ease; }
.yt-play::before { content: ''; margin-left: 7px; border-left: 28px solid var(--black); border-top: 17px solid transparent; border-bottom: 17px solid transparent; }
.yt-lite:hover .yt-play, .yt-lite:focus-visible .yt-play { transform: scale(1.08); }
.yt-label { position: absolute; left: 14px; bottom: 14px; background: var(--black); color: var(--yellow); font: 800 14px/1 var(--font-body); padding: 8px 14px; border-radius: 999px; }
.game-body { flex: 1; display: flex; flex-direction: column; gap: 20px; padding: 26px 26px 30px; }
.game-title { display: flex; align-items: center; gap: 14px; }
.game-icon { flex: none; width: 60px; height: 60px; display: grid; place-items: center; font-size: 30px; background: var(--yellow); border: 3px solid var(--black); border-radius: 16px; }
.game-title h3 { font-size: clamp(27px, 3vw, 36px); margin: 0; }
.game-title p { margin: 2px 0 0; color: var(--muted); font-weight: 800; }
.tags { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.tags li { background: var(--yellow-soft); border: 2px solid var(--black); border-radius: 999px; padding: 3px 12px; font-size: 14px; font-weight: 800; }
.game-desc p { margin: 0 0 10px; }
.game-desc p:last-child { margin-bottom: 0; }
.play-buttons { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.play-buttons .btn { flex-direction: column; gap: 6px; min-height: 100px; padding: 14px 8px; text-align: center; }
.play-buttons .btn svg { width: 28px; height: 28px; }
.btn-label { display: flex; flex-direction: column; line-height: 1.15; }
.btn-label small { font-size: 11px; font-weight: 800; letter-spacing: .6px; text-transform: uppercase; opacity: .85; }
.shots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.shots a { display: block; aspect-ratio: 4 / 3; overflow: hidden; background: var(--yellow-soft); border: 2px solid var(--black); border-radius: 12px; }
.shots img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
.shots a:hover img { transform: scale(1.06); }
.shots-title { margin: 0 0 -8px; font-size: 14px; font-weight: 800; letter-spacing: .6px; text-transform: uppercase; color: var(--muted); }

/* ---------- Features ---------- */
.features { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 20px; }
.feature { background: var(--white); border: 3px solid var(--black); border-radius: 18px; padding: 24px; box-shadow: 4px 4px 0 var(--black); }
.feature .emoji { font-size: 34px; line-height: 1; }
.feature h3 { font-size: 22px; margin: 12px 0 6px; }
.feature p { margin: 0; color: var(--muted); }

/* ---------- Story ---------- */
.story { background: var(--black); color: var(--white); }
.story .wrap { display: grid; grid-template-columns: 1.1fr .9fr; gap: 56px; align-items: center; }
.story h2 { font-size: clamp(32px, 4.2vw, 48px); margin: 14px 0 18px; }
.story h2 span { color: var(--yellow); }
.story p { color: #e6e6e6; font-size: 18px; }
.story .eyebrow { background: var(--yellow); color: var(--black); }
.paper { position: relative; transform: rotate(2deg); background: var(--white); color: var(--ink); border: 3px solid var(--yellow); border-radius: 18px; padding: 34px 30px 30px 54px; background-image: linear-gradient(90deg, transparent 38px, #f2b8b8 38px, #f2b8b8 40px, transparent 40px), repeating-linear-gradient(transparent 0 31px, #d9e4f2 31px 32px); box-shadow: 10px 10px 0 var(--yellow); }
.paper::before { content: '\270F\FE0F'; position: absolute; top: -26px; right: 22px; font-size: 44px; }
.paper blockquote { margin: 0; font-family: var(--font-display); font-size: clamp(21px, 2.4vw, 26px); line-height: 1.35; font-weight: 600; }
.paper figcaption { margin-top: 14px; font-weight: 800; color: var(--muted); }

/* ---------- FAQ ---------- */
.faq { max-width: 820px; margin: 0 auto; display: grid; gap: 14px; }
.faq details { background: var(--white); border: 3px solid var(--black); border-radius: 16px; box-shadow: 4px 4px 0 var(--black); }
.faq summary { cursor: pointer; list-style: none; padding: 18px 56px 18px 22px; position: relative; font-weight: 800; font-size: 18px; }
.faq summary::-webkit-details-marker { display: none; }
.faq summary::after { content: '+'; position: absolute; right: 18px; top: 50%; translate: 0 -50%; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; background: var(--yellow); border: 2px solid var(--black); font: 700 22px/1 var(--font-display); }
.faq details[open] summary::after { content: '\2212'; }
.faq details p { margin: 0; padding: 0 22px 20px; color: var(--muted); }

/* ---------- Follow ---------- */
.follow { background: var(--yellow); border-top: 3px solid var(--black); text-align: center; position: relative; overflow: hidden; }
.follow::before { content: ''; position: absolute; inset: 0; background-image: radial-gradient(rgba(0,0,0,.1) 2px, transparent 2.6px); background-size: 28px 28px; pointer-events: none; }
.follow .wrap { position: relative; }
.follow .section-head p { color: var(--ink); }
.social { display: flex; flex-wrap: wrap; justify-content: center; gap: 14px; margin: 0; padding: 0; list-style: none; }
.social a { display: inline-flex; align-items: center; gap: 10px; padding: 12px 20px; background: var(--white); border: 3px solid var(--black); border-radius: 999px; box-shadow: 4px 4px 0 var(--black); font-weight: 800; text-decoration: none; transition: transform .15s ease, box-shadow .15s ease, background .15s ease, color .15s ease; }
.social a:hover { background: var(--black); color: var(--yellow); transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--black); }
.social svg { width: 22px; height: 22px; fill: currentColor; flex: none; }

/* ---------- Footer ---------- */
.site-footer { background: var(--black); color: #cfcfcf; padding: 48px 0 36px; }
.site-footer .wrap { display: grid; gap: 22px; justify-items: center; text-align: center; }
.site-footer .brand { color: var(--white); }
.site-footer .brand .tere { color: var(--black); border-color: var(--yellow); }
.footer-social { display: flex; gap: 10px; list-style: none; margin: 0; padding: 0; }
.footer-social a { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; border: 2px solid #444; color: var(--white); transition: background .15s ease, color .15s ease, border-color .15s ease; }
.footer-social a:hover { background: var(--yellow); border-color: var(--yellow); color: var(--black); }
.footer-social svg { width: 20px; height: 20px; fill: currentColor; }
.footer-links { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 22px; list-style: none; margin: 0; padding: 0; }
.footer-links a { color: var(--white); font-weight: 700; text-decoration: none; }
.footer-links a:hover { color: var(--yellow); }
.footer-copy { margin: 0; font-size: 14px; }

/* ---------- Blog posts and pages (privacy policy, rules, news...) ---------- */
.content-area { min-height: 50vh; }
.entry { max-width: 800px; margin: 0 auto; padding: 48px 20px 80px; }
.entry h1 { font-size: clamp(32px, 5vw, 48px); margin: 0 0 24px; }
.entry-body { font-size: 18px; line-height: 1.75; }
.entry-body a { text-decoration: underline; text-decoration-color: var(--yellow); text-decoration-thickness: 3px; text-underline-offset: 3px; font-weight: 700; }
.entry-body img { height: auto !important; margin: 16px auto; border-radius: 14px; }
.entry-body iframe { width: 100% !important; height: auto !important; aspect-ratio: 16 / 9; border: 0; border-radius: 14px; }
.back-home { display: inline-block; margin-top: 40px; }
.post-list { max-width: 1100px; margin: 0 auto; padding: 48px 20px 80px; }
.post-list > h1 { font-size: clamp(30px, 4vw, 42px); margin: 0 0 28px; }
.post-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 24px; }
.post-card { border: 3px solid var(--black); border-radius: 18px; overflow: hidden; box-shadow: 4px 4px 0 var(--black); text-decoration: none; display: block; background: var(--white); }
.post-card img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; border-bottom: 3px solid var(--black); }
.post-card h2 { font-size: 22px; margin: 0; padding: 16px 18px 20px; }
.pager { display: flex; justify-content: center; gap: 14px; margin-top: 36px; }

/* ---------- Screenshot lightbox ---------- */
.lightbox { padding: 0; border: 3px solid var(--black); border-radius: 16px; background: var(--black); max-width: min(94vw, 1200px); max-height: 92vh; overflow: visible; }
.lightbox::backdrop { background: rgba(0,0,0,.82); }
.lightbox img { max-height: 86vh; width: auto; margin: 0 auto; border-radius: 13px; }
.lightbox-close { position: absolute; top: -18px; right: -18px; width: 44px; height: 44px; border-radius: 50%; border: 3px solid var(--black); background: var(--yellow); font: 700 24px/1 var(--font-display); cursor: pointer; }

/* ---------- Responsive ---------- */
@media (min-width: 960px) {
  .games-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 900px) {
  .hero .wrap { grid-template-columns: 1fr; padding-top: 44px; padding-bottom: 56px; gap: 10px; }
  .dice-stage { height: 190px; order: -1; max-width: 360px; width: 100%; margin: 0 auto; }
  .die { width: 104px; height: 104px; padding: 12px; border-radius: 22px; box-shadow: 6px 6px 0 var(--black); }
  .die i { width: 18px; height: 18px; }
  .pawn { transform: scale(.75); top: 40%; }
  .story .wrap { grid-template-columns: 1fr; gap: 48px; }
}
@media (max-width: 760px) {
  .main-nav a:not(.nav-cta) { display: none; }
  .section { padding: 60px 0; }
  .game-body { padding: 22px 18px 24px; }
  .play-buttons { gap: 10px; }
  .play-buttons .btn { min-height: 92px; padding: 12px 4px; font-size: 15px; }
  .social a span { display: none; }
  .social a { padding: 14px; }
  .social svg { width: 26px; height: 26px; }
}
@media (max-width: 380px) {
  .brand { font-size: 22px; }
  .brand img { height: 38px; }
  .play-buttons .btn { font-size: 14px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

body.script:
//
(function () {
  // Trailers: show the thumbnail first and load YouTube only when it is clicked.
  // youtube-nocookie.com does not set tracking cookies until the video plays.
  document.querySelectorAll('.yt-lite').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var iframe = document.createElement('iframe');
      iframe.src = 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(btn.dataset.id) + '?autoplay=1&rel=0&playsinline=1';
      iframe.title = btn.dataset.title || 'Game trailer';
      iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
      iframe.allowFullscreen = true;
      btn.parentNode.replaceChild(iframe, btn);
    });
  });

  // Posters: open full size in a lightbox (plain links still work without JS)
  var box = document.getElementById('lightbox');
  var boxImg = document.getElementById('lightbox-img');
  if (box && typeof box.showModal === 'function') {
    document.querySelectorAll('.shot').forEach(function (link) {
      link.addEventListener('click', function (e) {
        e.preventDefault();
        var img = link.querySelector('img');
        boxImg.src = link.href;
        boxImg.alt = img ? img.alt : '';
        box.showModal();
      });
    });
    box.querySelector('.lightbox-close').addEventListener('click', function () { box.close(); });
    box.addEventListener('click', function (e) { if (e.target === box) box.close(); });
  }

  var year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
})();
//
